{"path":"contact.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Connect — Contact | {{BUSINESS_NAME}}</title>
  <meta name="description" content="Reach out for events, private sessions, or questions about sound-focused immersive experiences in {{CITY}}, {{STATE}}." />
  <style>
    :root{
      --bg:#fbf7f1;--panel:#fff8f2;--muted:#6d5a4a;--accent:#8a5a3b;--accent-2:#c28b68;--glass:rgba(255,255,255,0.6);
      --radius:14px;--shadow:0 6px 24px rgba(104,73,58,0.12);
      --focus:3px rgba(138,90,59,0.18);
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
      color-scheme: light;
    }
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#fff);color:var(--muted);}
    /* Pattern background using external asset/img/pattern.svg */
    .page-hero{min-height:36vh;display:grid;align-items:center;padding:48px 20px;background-image:url("assets/img/pattern.svg");background-size:320px 320px;background-repeat:repeat;background-position:center;}
    .wrap{max-width:1100px;margin:0 auto;}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 20px;}
    .brand{display:flex;flex-direction:column;gap:4px}
    .brand h1{font-size:18px;margin:0;color:var(--accent);letter-spacing:0.6px}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-size:14px}
    /* hero card */
    .hero-card{background:linear-gradient(180deg,var(--panel),#fff);border-radius:var(--radius);box-shadow:var(--shadow);padding:22px;display:grid;grid-template-columns:1fr 360px;gap:18px;align-items:start}
    .hero-copy h2{margin:0 0 8px 0;color:#4b3528;font-size:22px}
    .hero-copy p{margin:0;color:#685649;line-height:1.45}
    .contact-form{background:rgba(255,255,255,0.85);padding:14px;border-radius:12px;border:1px solid rgba(160,129,107,0.06)}
    .field{display:flex;flex-direction:column;margin-bottom:10px}
    label{font-size:13px;color:#7a6150;margin-bottom:6px}
    input[type="text"],input[type="email"],textarea,select{padding:10px;border-radius:10px;border:1px solid rgba(120,93,74,0.12);font-size:14px}
    textarea{min-height:110px;resize:vertical}
    .btn{display:inline-flex;align-items:center;gap:8px;background:linear-gradient(180deg,var(--accent),var(--accent-2));color:white;padding:10px 14px;border-radius:10px;border:none;cursor:pointer}
    .ghost{background:transparent;border:1px solid rgba(120,93,74,0.1);color:var(--accent);}
    /* social proof strip */
    .proof{display:flex;gap:12px;align-items:center;padding:12px;border-radius:12px;margin-top:18px;background:linear-gradient(90deg,rgba(250,243,238,0.6),rgba(255,255,255,0.6));}
    .proof .dot{width:48px;height:48px;border-radius:8px;background:linear-gradient(180deg,#fff,rgba(255,255,255,0.6));display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    .columns{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:28px}
    section.card{background:var(--panel);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
    h3{margin:0 0 8px 0;color:#4b3528}
    .muted{color:#7a6150;font-size:14px}
    footer{padding:28px 20px;text-align:center;font-size:13px;color:#8b796b}
    /* reveal animation */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){
      .reveal{transition:none;opacity:1;transform:none}
    }
    /* Modal / guided exercise */
    .modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:24px;background:rgba(9,6,5,0.35);z-index:60}
    .modal[open]{display:flex}
    .modal-card{width:100%;max-width:720px;background:#fff;border-radius:16px;padding:20px;box-shadow:0 30px 80px rgba(53,28,12,0.3)}
    .modal-header{display:flex;justify-content:space-between;align-items:center}
    .exercise-stage{display:grid;grid-template-columns:1fr 220px;gap:16px;align-items:center}
    .breath-visual{width:100%;height:220px;display:flex;align-items:center;justify-content:center}
    .pulse{width:140px;height:140px;border-radius:50%;background:radial-gradient(circle at 30% 30%, #fff7f0, var(--accent-2));box-shadow:0 8px 24px rgba(138,90,59,0.16);display:flex;align-items:center;justify-content:center;font-weight:700;color:#4b2e1f}
    .controls{display:flex;flex-direction:column;gap:10px}
    .tiny{font-size:13px;color:#8b796b}
    .row{display:flex;gap:8px;align-items:center}
    /* small screens */
    @media (max-width:880px){
      .hero-card{grid-template-columns:1fr;}
      .exercise-stage{grid-template-columns:1fr}
      .columns{grid-template-columns:1fr}
    }
  </style>
</head>
<body>
  <header class="wrap">
    <div class="brand">
      <h1>{{BUSINESS_NAME}}</h1>
      <div class="tiny">A place for tuned reconnection</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Calendar</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Story</a>
      <a href="faq.html">Help</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="page-hero">
      <div class="wrap hero-card reveal" id="heroCard">
        <div class="hero-copy">
          <h2>Reach out to plan something careful and capacious</h2>
          <p>Whether you're planning a public gathering, a close private session, or you simply have a question — we listen. Share a bit about intent and timing; we'll respond with options tuned to your needs in {{CITY}}, {{STATE}}.</p>
          <div class="proof">
            <div class="dot">★</div>
            <div class="muted">Trusted by small studios, retreat hosts, and curious groups across the region.</div>
          </div>
          <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
            <button class="btn" id="tryBtn">Try the guided exercise</button>
            <a class="btn ghost" href="book.html">Book a consult</a>
          </div>
        </div>

        <aside class="contact-form" aria-labelledby="contactTitle">
          <h3 id="contactTitle">Send a message</h3>
          <form id="contactForm" method="post" action="{{PRIMARY_CTA_URL}}/contact" novalidate>
            <div class="field">
              <label for="name">Name</label>
              <input id="name" name="name" type="text" placeholder="Your full name" required />
            </div>
            <div class="field">
              <label for="email">Email</label>
              <input id="email" name="email" type="email" placeholder="you@example.com" required />
            </div>
            <div class="field">
              <label for="phone">Phone</label>
              <input id="phone" name="phone" type="text" placeholder="{{PHONE}}" />
            </div>
            <div class="field">
              <label for="inquiry">Inquiry type</label>
              <select id="inquiry" name="inquiry">
                <option>Public event / community</option>
                <option>Private session</option>
                <option>Retreat or partnership</option>
                <option>Other</option>
              </select>
            </div>
            <div class="field">
              <label for="message">Tell us what's bringing you</label>
              <textarea id="message" name="message" placeholder="Timing, audience, rough headcount, and anything special to note..."></textarea>
            </div>
            <div style="display:flex;gap:8px;align-items:center;justify-content:flex-end">
              <button type="submit" class="btn">Send message</button>
            </div>
            <div style="margin-top:10px;font-size:13px;color:#6f5b4a">Prefer a direct note? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</div>
          </form>
        </aside>
      </div>
    </section>

    <div class="wrap">
      <div class="columns">
        <section class="card reveal" id="socialProof">
          <h3>What people say</h3>
          <p class="muted">"A quieted pulse — we left with clearer edges and softer thinking. The setting and instruments allowed space for my thoughts to rearrange." — local organizer</p>
          <p class="muted" style="margin-top:10px">If you'd like references for event planning or accessibility needs, ask and we'll share details.</p>
        </section>

        <section class="card reveal" id="benefits">
          <h3>How a session can help</h3>
          <ul class="muted" style="padding-left:18px;margin:8px 0">
            <li>Lowered physical tension and clarified breath</li>
            <li>Structured space to anchor intentions before transitions</li>
            <li>Support for focus work, rest, or group cohesion</li>
          </ul>
          <div style="margin-top:8px;font-size:13px;color:#7a6150">Contraindications: Not advised for people with uncontrolled seizures, certain metallic implants, or those with violent psychiatric symptoms. If you have serious medical concerns, consult your clinician before participating. Notify us in advance of pregnancy, implants, or severe vestibular conditions.</div>
        </section>

        <section class="card reveal" id="process">
          <h3>How we work with organizers</h3>
          <p class="muted">We begin with a short consult to align intention, acoustics, and logistics. For group bookings we provide a timeline, instrument list, and care notes for participants.</p>
          <ol class="muted" style="padding-left:18px;margin-top:8px">
            <li>Discovery call — 20 minutes</li>
            <li>Site and access review</li>
            <li>Session outline and safety notes</li>
          </ol>
        </section>

        <section class="card reveal" id="faq">
          <h3>Fast answers</h3>
          <div class="muted">
            <strong>Do you travel?</strong> Yes — travel fees apply for distant locations. <br/>
            <strong>Are sessions loud?</strong> They are intentionally supportive rather than intrusive. We adapt volume for comfort. <br/>
            <strong>What should participants bring?</strong> A mat or cushion, a bottle of water, and an intention if they wish.
          </div>
        </section>
      </div>

      <section class="card reveal" id="calendarList" style="margin-top:22px">
        <h3>Upcoming gatherings</h3>
        <div class="muted">Next event: <strong>Feb 28 — Evening Sound Field</strong> — 7:00pm • Community Hall</div>
        <ul style="margin-top:12px" class="muted">
          <li>Mar 14 • Morning Clarity — 9:30am</li>
          <li>Mar 27 • Deep Reset (booking opens) — 6:30pm</li>
          <li>Apr 11 • Retreat sound co-facilitation — full day</li>
        </ul>
      </section>

    </div>

    <section class="wrap" style="margin-top:28px">
      <div class="card reveal" style="display:flex;gap:18px;align-items:center;justify-content:space-between">
        <div>
          <h3>Need a consultation?</h3>
          <p class="muted">Reserve a planning slot and we'll draft a tailored outline for your group.</p>
        </div>
        <div>
          <a class="btn" href="book.html">Reserve planning time</a>
        </div>
      </div>
    </section>
  </main>

  <footer>
    <div class="wrap">Questions or urgent needs: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>

  <!-- Guided exercise modal -->
  <div class="modal" id="exerciseModal" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal-card" role="document">
      <div class="modal-header">
        <strong>Short practice</strong>
        <div>
          <button id="closeModal" class="ghost">Close</button>
        </div>
      </div>

      <div style="margin-top:12px" class="exercise-stage">
        <div>
          <label class="tiny">Choose a practice</label>
          <div class="row" style="margin-top:8px">
            <button class="btn" data-mode="breath">Breathing</button>
            <button class="btn ghost" data-mode="journaling">Journaling</button>
            <button class="btn ghost" data-mode="intention">Intention</button>
          </div>

          <div id="stageContent" style="margin-top:14px">
            <div id="breathPanel" style="display:none">
              <div class="tiny">Follow the sphere. Breathe with the rise and fall.</div>
              <div class="breath-visual">
                <div class="pulse" id="pulse">Breathe</div>
              </div>
              <div class="row">
                <button class="btn" id="startBreath">Start 1:30</button>
                <button class="btn ghost" id="skipBreath">Skip</button>
              </div>
            </div>

            <div id="journPanel" style="display:none">
              <div class="tiny">A short prompt to write freely for two minutes.</div>
              <div style="margin-top:8px">
                <div class="muted">Prompt: "A small letting go I can do today is..."</div>
                <textarea id="journalText" placeholder="Write here for 2 minutes" style="width:100%;margin-top:8px"></textarea>
                <div style="margin-top:8px" class="row"><button class="btn" id="startJournal">Start 2:00</button><button class="btn ghost" id="skipJournal">Skip</button></div>
              </div>
            </div>

            <div id="intentPanel" style="display:none">
              <div class="tiny">Set a short, practical intention for the coming hour.</div>
              <div style="margin-top:8px">
                <input id="intentInput" placeholder="I intend to..." style="width:100%" />
                <div style="margin-top:8px" class="row"><button class="btn" id="saveIntent">Save intention</button></div>
              </div>
            </div>
          </div>

        </div>

        <aside style="display:flex;flex-direction:column;gap:8px">
          <div style="background:var(--panel);padding:12px;border-radius:10px">
            <div style="font-size:13px;color:#7a6150">Tips</div>
            <div class="muted" style="margin-top:6px">If breath makes you dizzy, breathe normally. Short practices are scaffolds — make them gentler if needed.</div>
          </div>

          <div style="background:linear-gradient(180deg,#fff8f2, #fff);padding:12px;border-radius:10px">
            <div class="tiny">Shareable note</div>
            <div class="muted" style="margin-top:6px">Copy this line into your calendar: "30m sound session planning with {{BUSINESS_NAME}}"</div>
          </div>
        </aside>
      </div>
    </div>
  </div>

  <script>
    (function(){
      // Scroll-triggered reveal with prefers-reduced-motion support
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = document.querySelectorAll('.reveal');
      if(prefersReduced){
        reveals.forEach(el => el.classList.add('visible'));
      } else if('IntersectionObserver' in window){
        const io = new IntersectionObserver((entries)=>{
          entries.forEach(e=>{
            if(e.isIntersecting){
              e.target.classList.add('visible');
              io.unobserve(e.target);
            }
          });
        },{threshold:0.12});
        reveals.forEach(r=>io.observe(r));
      } else {
        // fallback
        reveals.forEach(el => el.classList.add('visible'));
      }

      // Guided exercise modal logic
      const tryBtn = document.getElementById('tryBtn');
      const modal = document.getElementById('exerciseModal');
      const closeModal = document.getElementById('closeModal');
      const stageContent = document.getElementById('stageContent');
      const pulse = document.getElementById('pulse');

      function openModal(){
        modal.setAttribute('open','');
        modal.setAttribute('aria-hidden','false');
        // default to breath
        setMode('breath');
      }
      function close(){
        modal.removeAttribute('open');
        modal.setAttribute('aria-hidden','true');
        stopBreathTimer();
        stopJournalTimer();
      }
      tryBtn.addEventListener('click',openModal);
      closeModal.addEventListener('click',close);
      modal.addEventListener('click',(e)=>{ if(e.target === modal) close(); });

      // Mode switch
      document.querySelectorAll('[data-mode]').forEach(btn=>{
        btn.addEventListener('click',()=> setMode(btn.getAttribute('data-mode')));
      });

      function setMode(mode){
        document.getElementById('breathPanel').style.display = mode==='breath'? 'block':'none';
        document.getElementById('journPanel').style.display = mode==='journaling'? 'block':'none';
        document.getElementById('intentPanel').style.display = mode==='intention'? 'block':'none';
      }

      // Breath timer: 90s with expanding pulse
      let breathInterval=null;let breathRemaining=90;let breathRunning=false;
      const startBreath = document.getElementById('startBreath');
      const skipBreath = document.getElementById('skipBreath');
      startBreath.addEventListener('click',()=>{
        if(breathRunning) return; breathRunning=true; startBreath.textContent='Running...';
        breathRemaining=90; pulse.style.transition='transform 4s ease-in-out';
        breathInterval = setInterval(()=>{
          // cycle every 6s: inhale 3s, exhale 3s -> simulate with scale
          const phase = (90 - breathRemaining)%6;
          const scale = (phase < 3) ? 1.18 : 0.86;
          pulse.style.transform = `scale(${scale})`;
          breathRemaining -= 1;
          if(breathRemaining<=0){ stopBreathTimer(); startBreath.textContent='Start 1:30'; }
        },1000);
      });
      skipBreath.addEventListener('click',()=>{ stopBreathTimer(); });
      function stopBreathTimer(){ breathRunning=false; clearInterval(breathInterval); breathInterval=null; pulse.style.transform='none'; }

      // Journal timer: 120s
      let journalInterval=null; let journalRemaining=120; let journalRunning=false;
      const startJournal = document.getElementById('startJournal');
      const skipJournal = document.getElementById('skipJournal');
      startJournal.addEventListener('click',()=>{
        if(journalRunning) return; journalRunning=true; startJournal.textContent='Running...';
        journalRemaining=120; journalInterval=setInterval(()=>{
          journalRemaining-=1;
          if(journalRemaining<=0){ stopJournalTimer(); startJournal.textContent='Start 2:00'; }
        },1000);
      });
      skipJournal.addEventListener('click',()=>{ stopJournalTimer(); });
      function stopJournalTimer(){ journalRunning=false; clearInterval(journalInterval); journalInterval=null; }

      // Intent save
      document.getElementById('saveIntent').addEventListener('click',()=>{
        const val = document.getElementById('intentInput').value.trim();
        if(val) {
          navigator.clipboard && navigator.clipboard.writeText(val + ' — ' + '{{BUSINESS_NAME}}');
          alert('Saved to clipboard: "'+val+'"');
          close();
        } else alert('Type a short intention');
      });

      // Accessibility: trap focus when modal open
      document.addEventListener('keydown',(e)=>{
        if(e.key==='Escape') close();
      });

      // Basic form validation
      document.getElementById('contactForm').addEventListener('submit', function(ev){
        const name = this.name.value.trim(); const email = this.email.value.trim();
        if(!name || !email){ ev.preventDefault(); alert('Please include your name and email.'); }
      });

      // Small progressive enhancement: reveal hero card after load
      document.getElementById('heroCard').classList.add('visible');
    })();
  </script>
</body>
</html>"} 
